package com.financetrack.controller;
import com.financetrack.entity.*;import com.financetrack.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/budgets") public class BudgetController {
 public record BudgetRequest(@NotNull Long categoryId,@NotNull @DecimalMin("0.01")BigDecimal amount,@Min(1)@Max(12)int month,@Min(2020)@Max(2200)int year){}
 private final BudgetRepository budgets;private final CategoryRepository categories;private final ExpenseRepository expenses;private final UserRepository users;
 public BudgetController(BudgetRepository b,CategoryRepository c,ExpenseRepository e,UserRepository u){budgets=b;categories=c;expenses=e;users=u;}private Long uid(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();}
 @GetMapping public List<Map<String,Object>> list(@RequestParam(defaultValue="0")int year,@RequestParam(defaultValue="0")int month,Authentication a){LocalDate d=LocalDate.now();int y=year==0?d.getYear():year,m=month==0?d.getMonthValue():month;return budgets.findByUserIdAndYearAndMonth(uid(a),y,m).stream().map(b->{LocalDate from=LocalDate.of(y,m,1),to=from.withDayOfMonth(from.lengthOfMonth());BigDecimal spent=expenses.total(uid(a),from,to);return Map.<String,Object>of("id",b.getId(),"categoryId",b.getCategory().getId(),"category",b.getCategory().getName(),"amount",b.getAmount(),"spent",spent,"exceeded",spent.compareTo(b.getAmount())>0,"month",m,"year",y);}).toList();}
 @PostMapping public Map<String,Object> save(@Valid @RequestBody BudgetRequest r,Authentication a){Long id=uid(a);Category c=categories.findById(r.categoryId()).filter(x->x.getKind().equals("EXPENSE")).orElseThrow(()->new IllegalArgumentException("Categoría de gasto inválida"));Budget b=budgets.findByUserIdAndCategoryIdAndYearAndMonth(id,c.getId(),r.year(),r.month()).orElseGet(()->new Budget(users.findById(id).orElseThrow(),c,r.year(),r.month(),r.amount()));b.setAmount(r.amount());b=budgets.save(b);return Map.of("id",b.getId(),"category",c.getName(),"amount",r.amount(),"month",r.month(),"year",r.year());}
}
